package com.indiesoundquest.conversation.repository;
import com.indiesoundquest.conversation.domain.*; import java.util.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface ConversationRepository extends JpaRepository<Conversation,UUID>{ Optional<Conversation> findByIdAndGuestSessionIdAndStatusNot(UUID id,UUID guestId,ConversationStatus status); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select c from Conversation c where c.id=:id and c.guestSessionId=:guestId and c.status<>:status") Optional<Conversation> findLockedOwned(@Param("id")UUID id,@Param("guestId")UUID guestId,@Param("status")ConversationStatus status); List<Conversation> findByGuestSessionIdAndStatusNotOrderByLastMessageAtDesc(UUID guestId,ConversationStatus status); }
